.table_box {
  ::v-deep .el-input__inner {
    border: 1px solid #ddd;
  }
}

.xt-layout-sider {
  background-color: #cfe6f9;
  border-radius: 5px
}

::v-deep .el-tree {
  background: transparent;
  color: #46506d;
}

::v-deep .el-tree--highlight-current .el-tree-node.is-current > .el-tree-node__content {
  background: none
}

::v-deep .el-tree-node__content:hover {
  background: none
}

::v-deep .el-input__inner {
  border: none;
  // background: red;
  //border-radius: 999px;
}

.xt-layout-content {
  padding: 10px;
  background: #fff;
  border-radius: 5px;
}

.search_form {
  display: flex;
  padding: 15px 80px;
  // ::v-deep .el-button{
  //   padding: 12px 30px;
  //   height: 40px;
  //   font-size: 14px
  // }
}

.table_detial {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 10px;
  margin-top: 15px;

  .table_detial_l {
    color: #999;

    span {
      color: #333;
      font-weight: bold;
    }
  }

  .table_info {
    display: flex;

    .info_item {
      display: flex;
      align-items: center;
      font-size: 14px;
      margin-right: 30px;

      &:last-child {
        margin-right: 0;
      }

      img {
        margin-right: 7px
      }

      span {
        display: inline-block;
        line-height: 40px;
        color: #46506d;
        cursor: pointer;
      }

      i {
        font-style: normal;
        color: #409EFF;
        font-weight: 900;
        margin-left: 5px;

      }

    }
  }
}

.e_wd {
  width: 50%;
}
